/* Fleet full-screen-on-Edge setting.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * the per-app part is the `app` prefix the caller passes in.
 *
 * A managed phone's work-profile Edge cannot install a fleet app, so the app
 * runs in a tab with Edge's address bar and toolbar on top of it. This binds a
 * Settings row whose switch asks the Fullscreen API to hide them. The row is
 * shown only in Edge (user-agent token `Edg/` or `EdgA/`) and only where the
 * API exists; anywhere else it stays hidden and nothing changes.
 *
 * The choice is `localStorage['<app>.fullscreen']` = '1', off by default, kept
 * per device. A browser grants full screen to a user gesture only, so after a
 * reload the switch stays on and the first tap anywhere re-enters. Leaving by
 * hand (the back gesture, Esc) does not switch the setting off: the next tap
 * re-enters, and the switch is the way to turn it off.
 */

'use strict';

import { setSwitch } from '../switch/switch.js';

const EDGE_TOKEN = /\bEdgA?\//;

/**
 * Whether a user agent is Edge: desktop (`Edg/`) or Android (`EdgA/`).
 *
 * @param {string} [ua]  defaults to this browser's user agent.
 * @returns {boolean}
 */
export function isEdge(ua) {
  return EDGE_TOKEN.test(ua === undefined ? navigator.userAgent : String(ua));
}

function storageKey(app) {
  return app + '.fullscreen';
}

/**
 * Whether full screen is switched on for an app on this device.
 *
 * @param {string} app  the app's localStorage prefix (e.g. 'app-launcher').
 * @returns {boolean}
 */
export function readFullscreen(app) {
  try {
    return localStorage.getItem(storageKey(app)) === '1';
  } catch (e) {
    // Storage blocked (private mode, cleared site data): off.
    return false;
  }
}

function writeFullscreen(app, on) {
  try {
    if (on) localStorage.setItem(storageKey(app), '1');
    else localStorage.removeItem(storageKey(app));
  } catch (e) {
    // Not persisted; the choice still applies for this page view.
  }
}

function supported() {
  return !!(document.fullscreenEnabled && document.documentElement.requestFullscreen);
}

function enter() {
  // No user gesture, or the browser refused: the setting stays on and the next
  // tap tries again.
  Promise.resolve()
    .then(() => document.documentElement.requestFullscreen({ navigationUI: 'hide' }))
    .catch(() => {});
}

function leave() {
  if (!document.fullscreenElement) return;
  Promise.resolve()
    .then(() => document.exitFullscreen())
    .catch(() => {});
}

/**
 * Wire the Settings row and put the page back in full screen on a tap.
 *
 * @param {HTMLElement} row    the row holding the [data-fullscreen-toggle]
 *                             switch; shown only when this is Edge.
 * @param {string} app         the app's localStorage prefix.
 * @param {string} [ua]        a user agent to test against (default: this one).
 * @returns {boolean}          whether the row is shown.
 */
export function bindFullscreen(row, app, ua) {
  const toggle = row.querySelector('[data-fullscreen-toggle]');
  const show = !!toggle && isEdge(ua) && supported();
  row.hidden = !show;
  if (!show) return false;

  const paint = () => {
    setSwitch(toggle, readFullscreen(app));
    // Armed: on, but the page is not in full screen (after a reload, or a
    // back gesture): the row says a tap goes back in.
    row.dataset.armed = String(readFullscreen(app) && !document.fullscreenElement);
  };
  paint();

  toggle.addEventListener('click', () => {
    const on = !readFullscreen(app);
    writeFullscreen(app, on);
    if (on) enter();
    else leave();
    paint();
  });

  // One capture-phase tap anywhere re-enters; it still reaches its target. A
  // tap in the row itself is the switch's own and is left to it, or the
  // gesture that turns the setting off would put the page back in.
  document.addEventListener('click', (event) => {
    if (row.contains(event.target)) return;
    if (readFullscreen(app) && !document.fullscreenElement) enter();
  }, true);

  document.addEventListener('fullscreenchange', paint);
  return true;
}
